import { describe, it, expect } from "vitest";
import { slugify } from "../slugify";

export const TEST_FIXTURES = {
  TYPICAL: "Hello World",
  EDGES: ["", "x", "a".repeat(255)],
};

describe("slugify", () => {
  it("handles typical input", () => {
    expect(slugify(TEST_FIXTURES.TYPICAL)).toBe("hello-world");
  });

  it.each(TEST_FIXTURES.EDGES)("handles %s", (input) => {
    expect(typeof slugify(input)).toBe("string");
  });
});

import { describe, it, expect } from "vitest";
import { load } from "../loader";

const SAMPLE_PATHS = ["/etc/hosts", "/tmp/foo", "/var/log/bar"];

describe("load", () => {
  for (const p of SAMPLE_PATHS) {
    it(`loads ${p}`, async () => {
      const r = await load(p);
      expect(r).toBeDefined();
    });
  }
});

import { describe, it, expect } from "vitest";
import * as fc from "fast-check";
import { slugify } from "../slugify";

describe("slugify", () => {
  it.prop([fc.string({ minLength: 1, maxLength: 64 })])(
    "produces a kebab-case string for any non-empty input",
    (input) => {
      const result = slugify(input);
      expect(typeof result).toBe("string");
      expect(result).not.toMatch(/\s/);
    },
  );
});

import { describe, it, expect } from "vitest";
import { knownCommands, dispatch } from "../registry";

describe("dispatch", () => {
  for (const command of knownCommands) {
    it(`dispatches ${command.name}`, () => {
      const result = dispatch(command.name);
      expect(result.kind).toBe(command.expectedKind);
    });
  }
});
